function allPosts(){return [...data.posts,...seedPosts.map((p,i)=>({...p,createdAt:new Date(Date.UTC(2026,9,30-i,1,30)).toISOString(),sample:true}))].map(p=>({...p,...(data.postEdits?.[p.id]||{}),...(p.authorId===data.userId?{avatar:data.avatar,avatarImage:data.avatarImage,name:data.name}:{})})).filter(p=>!(data.deletedPosts||[]).includes(p.id))}
let postPhotos=[],photosLoading=false,photoDraft=0;
function postImages(p){return Array.isArray(p.images)?p.images:(p.image?[p.image]:[])}
function newId(){if(crypto.randomUUID)return crypto.randomUUID();return Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('')}
function formatDate(value){if(!value||!Number.isFinite(new Date(value).getTime()))return '日時の記録なし';return new Intl.DateTimeFormat('ja-JP',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value))}
