data.userId??=newId();
if(data.avatarCustom)data.avatarImage=customAvatarImage(data.avatarCustom);
for(const p of data.posts){p.authorId??=data.userId;if(!p.createdAt&&/^[pr]\d+$/.test(p.id)){const n=Number(p.id.slice(1));if(Number.isFinite(n)&&n>0)p.createdAt=new Date(n).toISOString()}}
