function scrapbookMoments(){return `<section class="moments-board" aria-label="船の上でのお楽しみ"><div class="moments-heading"><span class="tiny-kicker">船の上の楽しみ</span><h2>船の上で、<br>何をしよう。</h2><p>何もしない時間も、<br>船旅のごちそうです。</p><span class="hand-note">わたしの楽しみ、見つけた。</span></div><button type="button" class="polaroid moment-sea" onclick="column()"><span class="moment-photo"></span><span class="hand-note">海を眺めて、もう一杯。</span><small>朝のデッキで、のんびりと。</small><span class="card-destination">コラムを読む ${icon('arrow')}</span></button><button type="button" class="polaroid moment-port" onclick="go('stamp')"><span class="moment-photo"></span><span class="hand-note">次の港では、何に出会えるでしょう。</span><small>寄港地と、思い出のスタンプ帳へ。</small><span class="card-destination">スタンプ帳を見る ${icon('arrow')}</span></button></section>`}
